import { create_list_edit_delete_splay_questions } from "@/graphql/mutations";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "../SnackBar.vue";
export default {
  props: {
    DialogEditQuestion: Boolean,
    StoreObj: Object
  },
  components: {
    SnackBar
  },
  data: () => ({
    edited_question: "",
    edited_optionOne: "",
    edited_optiontwo: "",
    edited_optionThree: "",
    edited_optionFour: "",
    edited_answer: "",
    loading: false,
    correctOption: null,
    SnackBarComponent: {}
  }),
  watch: {
    DialogEditQuestion(val) {
      if (val) {
        this.edited_question = this.StoreObj.splay_question_text;
        this.edited_optionOne = this.StoreObj.splay_option_1;
        this.edited_optiontwo = this.StoreObj.splay_option_2;
        this.edited_optionThree = this.StoreObj.splay_option_3;
        this.edited_optionFour = this.StoreObj.splay_option_4;
        this.edited_answer = this.StoreObj.splay_correct_option;
        this.correctOption = this.StoreObj.splay_correct_option === this.StoreObj.splay_option_1 ? 1 : this.StoreObj.splay_correct_option === this.StoreObj.splay_option_2 ? 2 : this.StoreObj.splay_correct_option === this.StoreObj.splay_option_3 ? 3 : this.StoreObj.splay_correct_option === this.StoreObj.splay_option_4 ? 4 : null;
      }
    }
  },
  methods: {
    async ValidateForm() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.EditQuestion();
      }
    },
    async EditQuestion() {
      this.loading = true;
      try {
        const result = await API.graphql(graphqlOperation(create_list_edit_delete_splay_questions, {
          input: {
            action_type: "UPDATE",
            splay_category_id: this.StoreObj.splay_category_id,
            splay_question_id: this.StoreObj.splay_question_id,
            splay_question_text: this.edited_question,
            splay_option_1: this.edited_optionOne,
            splay_option_2: this.edited_optiontwo,
            splay_option_3: this.edited_optionThree,
            splay_option_4: this.edited_optionFour,
            splay_correct_option: this.edited_answer = this.correctOption === 1 ? this.edited_optionOne : this.correctOption === 2 ? this.edited_optiontwo : this.correctOption === 3 ? this.edited_optionThree : this.correctOption === 4 ? this.edited_optionFour : ""
          }
        }));
        let resultObj = JSON.parse(result.data.create_list_edit_delete_splay_questions);
        if (resultObj && resultObj.Status === "SUCCESS") {
          this.SnackBarComponent = {
            SnackbarVmodel: true,
            SnackbarColor: "green",
            SnackbarText: resultObj.Message
          };
        }
        this.loading = false;
        this.DialogEditQuestionEmit(2);
      } catch (error) {
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: "Failed to create question, try again"
        };
      }
      this.loading = false;
    },
    DialogEditQuestionEmit(Toggle) {
      this.$emit("clicked", Toggle);
    }
  }
};
